{
     "title": "CSCI-462: Introduction to Cryptography - Foundations & Application",
     "learningObjectives": [
       "Define the core components of cryptographic systems, including confidentiality, integrity, and authentication.",
       "Explain how mathematical foundations and standardized algorithms enable secure data protection.",
       "Apply cryptographic principles to evaluate real-world security implementations and identify common vulnerabilities."
     ],
     "beats": [
       {
         "title": "Lesson Title: Foundations of Cryptographic Systems",
         "claim": "Cryptography relies on mathematical foundations and standardized algorithms to protect data confidentiality, integrity, and authentication.",
         "example": "AES encryption uses a symmetric key to transform plaintext into ciphertext, ensuring only authorized parties can read the message.",
         "visualDirection": "Display a side-by-side comparison of plaintext and ciphertext with a symmetric key lock icon, labeled 'Confidentiality via AES'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       },
       {
         "title": "Lesson Title: Classical Cryptosystems Overview",
         "claim": "Classical cryptosystems like substitution and transposition ciphers form the historical basis for modern encryption techniques.",
         "example": "The Caesar cipher shifts each letter by a fixed number, demonstrating how simple substitution can be broken with frequency analysis.",
         "visualDirection": "Show a Caesar cipher alphabet wheel with 'A' shifting to 'D', annotated with 'Substitution Vulnerability'.",
         "sourceIds": ["rit-csci-462"]
       },
       {
         "title": "Lesson Title: Private-Key Cryptosystems",
         "claim": "Private-key cryptosystems use a single shared secret key for both encryption and decryption, enabling efficient symmetric encryption.",
         "example": "DES and AES require the same key for encrypting and decrypting data, making them fast but dependent on secure key distribution.",
         "visualDirection": "Illustrate a two-way arrow between 'Sender' and 'Receiver' with a single key symbol, labeled 'Symmetric Key Exchange'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       },
       {
         "title": "Lesson Title: Public-Key Cryptosystems",
         "claim": "Public-key cryptosystems use a mathematically linked key pair, allowing secure communication without prior key exchange.",
         "example": "RSA uses a public key for encryption and a private key for decryption, solving the key distribution problem in symmetric systems.",
         "visualDirection": "Draw a split key icon: 'Public Key' (open hand) and 'Private Key' (closed fist), labeled 'Asymmetric Key Pair'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       },
       {
         "title": "Lesson Title: Hashing Functions",
         "claim": "Hashing algorithms produce fixed-size outputs from variable-size inputs, enabling data integrity verification and collision resistance.",
         "example": "SHA-256 generates a unique 256-bit hash for a document, where altering any bit changes the entire output.",
         "visualDirection": "Show a document entering a hash function box, outputting a long hex string, labeled 'Integrity Check via SHA-256'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       },
       {
         "title": "Lesson Title: Data Integrity and Authentication",
         "claim": "Message authentication and digital signatures ensure data has not been tampered with and verify the sender's identity.",
         "example": "A digital signature uses the sender's private key to sign a message, which the receiver verifies with the public key.",
         "visualDirection": "Display a document with a signature stamp and a verification checkmark, labeled 'Authenticity via Digital Signatures'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       },
       {
         "title": "Lesson Title: Key Management Practices",
         "claim": "Secure key management covers generation, distribution, storage, rotation, and destruction to prevent unauthorized access.",
         "example": "Keys must be stored in hardware security modules and rotated regularly to limit exposure if compromised.",
         "visualDirection": "Show a key lifecycle diagram: 'Generate' -> 'Store' -> 'Use' -> 'Rotate' -> 'Destroy', with lock icons at each stage.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Lesson Title: Modes of Operation",
         "claim": "Modes of operation define how block ciphers process data larger than one block, enabling efficient encryption of arbitrary-length messages.",
         "example": "CBC mode uses a chaining value to link blocks, preventing pattern repetition in encrypted output.",
         "visualDirection": "Illustrate a block cipher processing two blocks with a feedback loop, labeled 'CBC Mode Chaining'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Lesson Title: Security Implementation & Validation",
         "claim": "Security depends on complete protocol design and implementation validation, not just algorithm selection, to prevent side-channel attacks.",
         "example": "Timing attacks can exploit variable execution times in cryptographic libraries, requiring constant-time implementations for validation.",
         "visualDirection": "Show a security checklist with items: 'Algorithm Validated', 'Implementation Tested', 'Side-Channel Mitigated', labeled 'Validation Checklist'.",
         "sourceIds": ["nist-cryptographic-standards", "nist-ssdf"]
       },
       {
         "title": "Lesson Title: Practical Analysis Checklist",
         "claim": "Students must evaluate cryptographic systems by checking key management, algorithm standards, integrity mechanisms, and implementation security.",
         "example": "A secure system uses AES for confidentiality, SHA-256 for integrity, RSA for authentication, and follows NIST key management standards.",
         "visualDirection": "Display a practical analysis checklist with checkboxes: 'Confidentiality Mechanism', 'Integrity Check', 'Authentication Method', 'Key Management', 'Implementation Validated'.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-462"]
       }
     ]
   }
